import { edit_or_delete_dashboard_topic } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    custom_details: Object,
    delete_customdashboard: Boolean
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    delete_customdashboard: {
      async handler() {
        if (this.delete_customdashboard == true) {
          //  console.log(this.custom_details.dashboard_created_by)   ;
          //  console.log( this.$store.getters.GetUserObj.user.user_email_id);
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_or_delete_dashboard_topic, {
          input: {
            action_type: "DELETE",
            dashboard_id: this.custom_details.dashboard_id,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.edit_or_delete_dashboard_topic);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("deleteMSg", "deleted Dashboard");
          // this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
